fn get_column(input: &Vec<Vec<i8>>, j: usize, _m: usize, n: usize) -> Vec<i8> {
    // Preallocate a vector with capacity n for efficiency
    let mut col = Vec::with_capacity(n);
    // Collect the j-th element from each of the n rows
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Preallocate the result with m rows (each will have length n)
    let mut result = Vec::with_capacity(m);
    // For each column index j in 0..m, extract that column as a row in the result
    for j in 0..m {
        result.push(get_column(&input, j, m, n));
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_get_column() {
        let matrix = vec![
            vec![1, 2, 3],
            vec![4, 5, 6],
            vec![7, 8, 9],
        ];
        // Extract the 1st column (index 1): [2, 5, 8]
        assert_eq!(get_column(&matrix, 1, 3, 3), vec![2, 5, 8]);
    }

    #[test]
    fn test_column_stack_square() {
        let matrix = vec![
            vec![1, 2, 3],
            vec![4, 5, 6],
            vec![7, 8, 9],
        ];
        let transposed = column_stack(matrix, 3, 3);
        let expected = vec![
            vec![1, 4, 7],
            vec![2, 5, 8],
            vec![3, 6, 9],
        ];
        assert_eq!(transposed, expected);
    }

    #[test]
    fn test_column_stack_rectangular() {
        let matrix = vec![
            vec![10, 20],
            vec![30, 40],
            vec![50, 60],
        ]; // 3x2 matrix
        // Transposed is 2x3:
        // [
        //   [10, 30, 50],
        //   [20, 40, 60],
        // ]
        let transposed = column_stack(matrix, 2, 3);
        let expected = vec![
            vec![10, 30, 50],
            vec![20, 40, 60],
        ];
        assert_eq!(transposed, expected);
    }
}